def link_existing_countries(apps, schema_editor):
    Country = apps.get_model('core', 'Country')
    Country.objects.get_or_create(slug='morocco', defaults={'name': 'Morocco', 'is_active': True})
    Country.objects.get_or_create(slug='ireland', defaults={'name': 'Ireland', 'is_active': False})
    for name in ['BlogPost', 'BookingNotificationSettings', 'ContactEmailSettings', 'ContactMessage', 'CountryContent', 'Destination', 'GuideCalendar', 'Information', 'Promotion', 'Section', 'Tour']:
        Model = apps.get_model('core', name)
        for slug in Model.objects.exclude(country='').values_list('country', flat=True).distinct():
            Country.objects.get_or_create(slug=slug, defaults={'name': slug.replace('-', ' ').title()})
            Model.objects.filter(country=slug).update(region_id=slug)
    apps.get_model('core', 'SiteSettings').objects.get_or_create(pk=1)


